/**
 * Local stand-ins for the Anthropic and ElevenLabs APIs, so the full live
 * pipeline (record → transcribe → translate → speak) can be tested end to end
 * without real keys or credits.
 *
 *   node scripts/mock-providers.mjs            # listens on :4010
 *   ANTHROPIC_API_KEY=test ANTHROPIC_BASE_URL=http://localhost:4010 \
 *   ELEVENLABS_API_KEY=test ELEVENLABS_BASE_URL=http://localhost:4010/v1 npx expo start
 */
import http from 'node:http';

const PORT = Number(process.env.MOCK_PORT || 4010);
const seen = [];

// A tiny valid MP3 frame (silence), so audio players accept the response.
const SILENT_MP3 = Buffer.from(
  '',
  'base64',
);

function body(req) {
  return new Promise((res) => {
    const chunks = [];
    req.on('data', (c) => chunks.push(c));
    req.on('end', () => res(Buffer.concat(chunks)));
  });
}

http
  .createServer(async (req, res) => {
    const raw = await body(req);
    const url = req.url ?? '';
    seen.push(`${req.method} ${url.split('?')[0]}`);

    if (url.startsWith('/__seen')) {
      res.end(JSON.stringify(seen));
      return;
    }

    if (url.startsWith('/v1/messages')) {
      const payload = JSON.parse(raw.toString());
      const text = payload.messages[0].content;
      const utter = text.match(/<utterance>([\s\S]*)<\/utterance>/)?.[1] ?? '';
      const japanese = /[぀-ヿ一-龯]/.test(utter);
      const out = japanese
        ? { source_language: 'ja', translation: 'Where is the station?', romanization: null }
        : { source_language: 'en', translation: '駅はどこですか？', romanization: 'eki wa doko desu ka?' };
      res.setHeader('content-type', 'application/json');
      res.end(
        JSON.stringify({
          id: 'msg_mock',
          type: 'message',
          role: 'assistant',
          model: payload.model,
          content: [{ type: 'text', text: JSON.stringify(out) }],
          stop_reason: 'end_turn',
          stop_sequence: null,
          usage: { input_tokens: 10, output_tokens: 10 },
        }),
      );
      return;
    }

    if (url.startsWith('/v1/speech-to-text')) {
      res.setHeader('content-type', 'application/json');
      res.end(JSON.stringify({ text: '駅はどこですか', language_code: 'jpn', language_probability: 0.98 }));
      return;
    }

    if (url.startsWith('/v1/text-to-speech/')) {
      res.setHeader('content-type', 'audio/mpeg');
      res.end(SILENT_MP3);
      return;
    }

    res.statusCode = 404;
    res.end('not found');
  })
  .listen(PORT, () => console.log(`mock providers on :${PORT}`));
